/**
 * @param {number} n
 * @param {number} m
 * @return {number}
 */
var differenceOfSums = function(n, m) {
    const total = Math.floor(n * (n + 1) / 2);
    const k = Math.floor(n / m);
    const divSum = Math.floor(m * k * (k + 1) / 2);
    return total - 2 * divSum;
};
